public class Solution {
    public int solve(int[] A, int B) {
        long MOD = 1000000007L;
        int left = 0, right = A.length - 1;
        long count = 0;
        while (left < right) {
            long sum = (long) A[left] + A[right];
            if (sum < B) {
                left++;
            } else if (sum > B) {
                right--;
            } else if (A[left] == A[right]) {
                long c = right - left + 1;
                count = (count + c * (c - 1) / 2) % MOD;
                break;
            } else {
                long c1 = 1, c2 = 1;
                while (left + 1 < right && A[left + 1] == A[left]) { c1++; left++; }
                while (right - 1 > left && A[right - 1] == A[right]) { c2++; right--; }
                count = (count + c1 * c2) % MOD;
                left++;
                right--;
            }
        }
        return (int) (count % MOD);
    }
}

