public class Solution {
    public int solve(int[] A, int B) {
        HashMap<Integer, Integer> freq = new HashMap<>();
        for (int x : A) {
            freq.put(x, freq.getOrDefault(x, 0) + 1);
        }
        int count = 0;
        if (B == 0) {
            for (int v : freq.keySet()) {
                if (freq.get(v) >= 2) count++;
            }
            return count;
        }
        for (int v : freq.keySet()) {
            if (freq.containsKey(v + B)) count++;
        }
        return count;
    }
}

