public class Solution {
    public int solve(int[] A, int B) {
        final int MOD = 1_000_000_007;
        int n = A.length;
        long ans = 0;
        int l = 0, r = n - 1;
        while (l < r) {
            if ((long) A[l] * A[r] < B) {
                ans = (ans + 2L * (r - l)) % MOD;
                l++;
            } else {
                r--;
            }
        }
        for (int i = 0; i < n; i++) {
            if ((long) A[i] * A[i] < B) {
                ans = (ans + 1) % MOD;
            }
        }
        return (int) ans;
    }
}

