public class Solution {
    public int[] solve(int[] A, int[] B, int C) {
        int i = 0, j = B.length - 1;
        long best = Long.MAX_VALUE;
        int resA = A[0], resB = B[0];
        while (i < A.length && j >= 0) {
            long sum = (long) A[i] + B[j];
            long dist = Math.abs(sum - C);
            if (dist < best) {
                best = dist;
                resA = A[i];
                resB = B[j];
            }
            if (sum < C) {
                i++;
            } else {
                j--;
            }
        }
        return new int[]{resA, resB};
    }
}

public class Solution {
    public int maxArea(int[] A) {
        int l = 0, r = A.length - 1, best = 0;
        while (l < r) {
            int area = (r - l) * Math.min(A[l], A[r]);
            best = Math.max(best, area);
            if (A[l] < A[r]) {
                l++;
            } else {
                r--;
            }
        }
        return best;
    }
}

public class Solution {
    public int[] solve(int[] A, int B) {
        int left = 0;
        int n = A.length;
        int currentSum = 0;
        for(int i=0; i<n;i++){
            currentSum += A[i];
            while(currentSum > B){
                currentSum = currentSum - A[left];
                left++;
            }
            if(currentSum == B){
                int[] res = new int[i-left+1];
                int idx = 0;
                for(int j = left; j <= i; j++){
                    res[idx] = A[j];
                    idx++;
                }
                return res;
            }
        }
        return new int[]{-1};
    }
}

public class Solution {
    public int minimize(final int[] A, final int[] B, final int[] C) {
        int i = 0, j = 0, k = 0;
        int ans = Integer.MAX_VALUE;
        while (i < A.length && j < B.length && k < C.length) {
            int cur = Math.max(Math.abs(A[i] - B[j]),
                        Math.max(Math.abs(B[j] - C[k]), Math.abs(C[k] - A[i])));
            ans = Math.min(ans, cur);
            int min = Math.min(A[i], Math.min(B[j], C[k]));
            if (A[i] == min) i++;
            else if (B[j] == min) j++;
            else k++;
        }
        return ans;
    }
}

public class Solution {
    public int[] maxone(int[] A, int B) {
        int left = 0, zeroCount = 0;
        int bestLeft = 0, bestLen = 0;
        for (int right = 0; right < A.length; right++) {
            if (A[right] == 0) zeroCount++;
            while (zeroCount > B) {
                if (A[left] == 0) zeroCount--;
                left++;
            }
            if (right - left + 1 > bestLen) {
                bestLen = right - left + 1;
                bestLeft = left;
            }
        }
        int[] res = new int[bestLen];
        for (int i = 0; i < bestLen; i++) res[i] = bestLeft + i;
        return res;
    }
}
